data.minimal_example:
import 'package:reflection_factory/reflection_factory.dart';

part 'some_source_file.reflection.g.dart';

@EnableReflection()
class User {
  String? email;
  User(this.email);
}

void main() {
  var user = User('joe@mail.com');
  var userReflection = user.reflection;
  print('email: ${userReflection.field('email')?.get()}');
}
